 * Rejects creating an owner when the owner's city already contains {@value #CITY_OWNER_LIMIT} or
 * more owners, comparing cities case-insensitively. Runs before {@link BuildOwner}/{@link SaveOwner}
 * so the clash is a 409 (Conflict) rather than a persisted row.
 *
 * <p>Also exposes a read-time {@link #isWarning(OwnerRepository, String) capacity warning} — {@code
 * true} once a city holds between {@value #CITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1}
 * owners — so a response can flag that a city is approaching the hard limit.
 */
public class EnsureOwnerCityCapacity {

    /** Maximum number of owners permitted in a single city. */
    static final int CITY_OWNER_LIMIT = 50;

    /** A city holding this many owners (up to, but not including, the limit) raises the warning. */
    static final int CITY_WARNING_THRESHOLD = 40;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        if (countOwnersInCity(ownerRepository, city) >= CITY_OWNER_LIMIT) {
            throw new CityAtCapacityException(city, CITY_OWNER_LIMIT);
        }
    }

    /**
     * Whether {@code city} is approaching the per-city capacity limit: {@code true} when it already
     * holds between {@value #CITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1} owners
     * (inclusive), counting cities case-insensitively. At or beyond the hard limit this is
     * {@code false} — the city is at capacity, not merely approaching it.
     */
    public static boolean isWarning(OwnerRepository ownerRepository, String city) {
        int count = countOwnersInCity(ownerRepository, city);
        return count >= CITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
    }

    private static int countOwnersInCity(OwnerRepository ownerRepository, String city) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        return count;
    }
}

